import { readClientPicker } from "@/lib/reads";

import ClientPicker from "@/components/common/client-picker";
import JoinClients from "@/components/common/join-clients";

export const metadata: Metadata = { title: "Pick" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell.
async function Sections() {
    await connection();
    const loaded = await must(api.clients.list());
    const props1 = await readClientPicker(loaded);
    return (
        <>
            {props1.clients.length === 0 ? <p className="mx-auto w-full max-w-5xl px-4 py-16 text-center text-muted-foreground sm:px-6">{"No clients yet."}</p> : <ClientPicker {...props1} />}
            <JoinClients />
        </>
    );
}
